/*
 * model.h: on-device classifier (PRD 7.3): z-score + MLP (float32), and the
 * threshold baseline. Weights and parameters are generated by
 * ml/export_c.py into model_weights.h / model_params.h; until a model is
 * trained, the placeholder headers make model_available() false.
 */
#ifndef MODEL_H
#define MODEL_H

#include <stdbool.h>

#include "dsp/features.h"
#include "model/model_params.h"

#define CLS_STILL   0
#define CLS_CARRIED 1
#define CLS_ROUGH   2
#define CLS_ACCESS  3

/* Feature indices used by the baseline and the UI "why" line (ml/common.py). */
#define FI_AMAG_MEAN      0
#define FI_AMAG_STD       1
#define FI_JERK_PEAK      32
#define FI_TILT           36
#define FI_ALS_LOGMEAN    37
#define FI_ALS_LOGRANGE   38
#define FI_PS_MAX         40
#define FI_PS_NEAR        41

bool model_available(void);
const char *model_version(void);
const char *model_class_name(int c);       /* "STILL" ... */
const char *model_feature_name(int i);

/* Features -> class probabilities (softmax). Returns the argmax, or -1 when
   no model is available. */
int model_infer(const float feat[FEAT_N], float prob[MODEL_N_CLASSES]);

/* Rule baseline (ml/baseline.py) with the exported thresholds. */
int baseline_classify(const float feat[FEAT_N]);

#endif /* MODEL_H */
